void ped_alg::thread_ped_val_o() {
    if (esl_seteq<1,1,1>(ap_const_logic_1, ap_CS_fsm_state3.read())) {
        if (esl_seteq<1,1,1>(icmp_ln49_fu_254_p2.read(), ap_const_lv1_1)) {
            ped_val_o = add_ln50_fu_273_p2.read();
        } else if ((esl_seteq<1,1,1>(ap_const_lv1_0, icmp_ln49_fu_254_p2.read()) && 
                    esl_seteq<1,1,1>(icmp_ln54_fu_260_p2.read(), ap_const_lv1_1))) {
            ped_val_o = add_ln55_fu_266_p2.read();
        } else {
            ped_val_o = ped_val_i.read();
        }
    } else {
        ped_val_o = ped_val_i.read();
    }
}

