void ped_alg::thread_ap_NS_fsm() {
    switch (ap_CS_fsm.read().to_uint64()) {
        case 1 : 
            if ((esl_seteq<1,1,1>(ap_const_logic_1, ap_CS_fsm_state1.read()) && esl_seteq<1,1,1>(ap_start.read(), ap_const_logic_1) && esl_seteq<1,1,1>(or_ln28_1_fu_195_p2.read(), ap_const_lv1_1))) {
                ap_NS_fsm = ap_ST_fsm_state5;
            } else if ((esl_seteq<1,1,1>(ap_const_logic_1, ap_CS_fsm_state1.read()) && esl_seteq<1,1,1>(ap_start.read(), ap_const_logic_1) && esl_seteq<1,1,1>(or_ln28_1_fu_195_p2.read(), ap_const_lv1_0))) {
                ap_NS_fsm = ap_ST_fsm_state2;
            } else {
                ap_NS_fsm = ap_ST_fsm_state1;
            }
            break;
        case 2 : 
            ap_NS_fsm = ap_ST_fsm_state3;
            break;
        case 4 : 
            ap_NS_fsm = ap_ST_fsm_state4;
            break;
        case 8 : 
            ap_NS_fsm = ap_ST_fsm_state5;
            break;
        case 16 : 
            ap_NS_fsm = ap_ST_fsm_state1;
            break;
        default : 
            ap_NS_fsm = "XXXXX";
            break;
    }
}

void ped_alg::thread_hdltv_gen() {
    const char* dump_tv = std::getenv("AP_WRITE_TV");
    if (!(dump_tv && string(dump_tv) == "on")) return;

    wait();

    mHdltvinHandle << "[ " << endl;
    mHdltvoutHandle << "[ " << endl;
    int ap_cycleNo = 0;
    while (1) {
        wait();
        const char* mComma = ap_cycleNo == 0 ? " " : ", " ;
        mHdltvinHandle << mComma << "{"  <<  " \"ap_rst\" :  \"" << ap_rst.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"ap_start\" :  \"" << ap_start.read() << "\" ";
        mHdltvoutHandle << mComma << "{"  <<  " \"ap_done\" :  \"" << ap_done.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_idle\" :  \"" << ap_idle.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_ready\" :  \"" << ap_ready.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"ped_val_i\" :  \"" << ped_val_i.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ped_val_o\" :  \"" << ped_val_o.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ped_val_o_ap_vld\" :  \"" << ped_val_o_ap_vld.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"accum_i\" :  \"" << accum_i.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"accum_o\" :  \"" << accum_o.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"accum_o_ap_vld\" :  \"" << accum_o_ap_vld.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ADC\" :  \"" << ADC.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ADC_ap_vld\" :  \"" << ADC_ap_vld.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"tdata\" :  \"" << tdata.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"tvalid\" :  \"" << tvalid.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"tkeep0\" :  \"" << tkeep0.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"tkeep1\" :  \"" << tkeep1.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"tready\" :  \"" << tready.read() << "\" ";
        mHdltvinHandle << "}" << std::endl;
        mHdltvoutHandle << "}" << std::endl;
        ap_cycleNo++;
    }
}

